Steps:
[AUTH role=ADMIN_DEFAULT]
[REST-OP rbac]
POST {{BACK_URL}}/api/punchout-user-mappings
Content-Type: application/json
Body: {"externalId":"AGENT-TEST-PO-RBAC","userId":"{{mapUser}}","memberId":"{{mapMember}}","isActive":true}
[REST-EXEC rbac]
[REST-CAPTURE rbac.body.id → RBAC_ID]
[AUTH] password grant for {{viewer}} against {{BACK_URL}}/connect/token (grant_type=password, username={{viewer}}, password={{viewerPassword}}); keep the access_token as VIEWER_TOKEN
[HTTP] POST /api/punchout-user-mappings/search as VIEWER_TOKEN, body {"keyword":"AGENT-TEST-PO-RBAC","take":10}
[HTTP] POST /api/punchout-user-mappings as VIEWER_TOKEN, body {"externalId":"AGENT-TEST-PO-RBAC-W","userId":"{{mapUser}}","memberId":"{{mapMember}}","isActive":true}
[HTTP] PUT /api/punchout-user-mappings as VIEWER_TOKEN, body {"id":"{{RBAC_ID}}","externalId":"AGENT-TEST-PO-RBAC","userId":"{{mapUser}}","memberId":"{{mapMember}}","isActive":false}
[HTTP] DELETE /api/punchout-user-mappings?ids={{RBAC_ID}} as VIEWER_TOKEN
[AUTH] password grant for {{noperm}} as above; keep the access_token as NONE_TOKEN
[HTTP] POST /api/punchout-user-mappings/search as NONE_TOKEN, body {"keyword":"AGENT-TEST-PO-RBAC","take":10}
[AUTH] ADMIN_DEFAULT token again
[HTTP] POST /api/punchout-user-mappings/search body {"keyword":"AGENT-TEST-PO-RBAC","take":10}

